{"implementation":"def solve(case):
    if not isinstance(case, dict) or 'tokens' not in case or 'calls' not in case:
        raise ValueError('Invalid case structure')
    tokens = case['tokens']
    calls = case['calls']
    if not isinstance(tokens, list) or not isinstance(calls, list):
        raise ValueError('tokens and calls must be lists')
    for call in calls:
        for key in ['call_id', 'start', 'end', 'score', 'replacement_tokens']:
            if key not in call:
                raise ValueError(f'Missing required field: {key}')
        if not isinstance(call['replacement_tokens'], list):
            raise ValueError('replacement_tokens must be a list')
        if not isinstance(call['start'], int) or not isinstance(call['end'], int):
            raise ValueError('start and end must be integers')
        if call['start'] < 0 or call['end'] > len(tokens) or call['start'] >= call['end']:
            raise ValueError('Invalid span')
    sorted_calls = sorted(calls, key=lambda c: (-c['score'], c['start'], c['call_id']))
    accepted = []
    intervals = []
    for c in sorted_calls:
        s, e = c['start'], c['end']
        overlap = any(s < aend and astart < e for astart, aend in intervals)
        if not overlap:
            accepted.append(c)
            intervals.append((s, e))
    accepted_sorted = sorted(accepted, key=lambda c: c['start'])
    selected_ids = [c['call_id'] for c in accepted_sorted]
    result = tokens[:]
    for c in sorted(accepted, key=lambda c: c['start'], reverse=True):
        s, e = c['start'], c['end']
        result[s:e] = c['replacement_tokens']
    return {'selected_ids': selected_ids, 'output_tokens': result}"}
